 Creating a complex smart contract involves writing a self-executing program on a blockchain that automates the enforcement of an agreement between parties. Here's a simplified example of a smart contract for a real estate transaction, which includes multiple functions and conditions:

```solidity
pragma solidity ^0.8.0;

contract RealEstateContract {
    address public buyer;
    address public seller;
    uint public propertyId;
    uint public price;
    bool public isPurchased = false;

    constructor(uint _propertyId, uint _price) public {
        require(_propertyId > 0, "Property ID must be greater than 0.");
        require(_price > 0, "Property price must be greater than 0.");
    }

    function buyProperty(address _buyer, address _seller) public {
        require(msg.sender == _buyer, "Only the buyer can call this function.");
        require(_seller == buyers[_propertyId], "The seller must be the current owner of the property.");
        require(isPurchased == false, "The property is already purchased.");
        require(msg.value == price, "The buyer must pay the full price.");

        buyer = _buyer;
        seller = _seller;
        isPurchased = true;
    }

    function transferOwnership(address newOwner) public {
        require(msg.sender == buyer, "Only the current owner can transfer ownership.");
        require(newOwner != address(0), "The new owner must be a valid address.");
        buyer = newOwner;
    }
}
```

This smart contract allows a buyer to purchase a property from a seller. The contract checks that the buyer is the one calling the function, the seller is the current owner of the property, the property is not already purchased, and the buyer pays the full price. Once the conditions are met, the ownership of the property is transferred to the buyer. The contract also includes a function for the owner to transfer the property to a new owner.

